artists_without_2004_exhibition = artists.WHERE(
    HASNOT(exhibitions.WHERE(year == '2004')) == 1
).CALCULATE(
    artist_name=name
)

latest_contact_channel_date = customer.WHERE(
    LOWER(customer_name) == LOWER("Tillman Ernser")
).customer_contact_channel.CALCULATE(
    latest_active_to_date=active_to_date.MAX()
).FIRST().latest_active_to_date

columbus_crew_players_info = teams.WHERE(
    name == "Columbus Crew"
).players.CALCULATE(
    player_name=player,
    years_played=years_played
)

average_ages = GRAPH.CALCULATE(
    average_loser_age=AVG(
        IFF(
            (match.loser_age == '') | (match.loser_age == 'N/A') | (match.loser_age == 'Unknown') | (match.loser_age == '-') | CONTAINS(match.loser_age, '-') | CONTAINS(match.loser_age, '/'),
            NULL,
            match.loser_age
        ).TO_FLOAT()
    ),
    average_winner_age=AVG(
        IFF(
            (match.winner_age == '') | (match.winner_age == 'N/A') | (match.winner_age == 'Unknown') | (match.winner_age == '-') | CONTAINS(match.winner_age, '-') | CONTAINS(match.winner_age, '/'),
            NULL,
            match.winner_age
        ).TO_FLOAT()
    )
)

num_project_members = GRAPH.CALCULATE(
    num_project_members=COUNT(
        Project_Staff.WHERE(
            (role_code == 'leader') | (date_from < '1989-04-24 23:51:54')
        )
    )
)

customers_without_accounts = customer.CALCULATE(
    num_accounts=COUNT(account)
).WHERE(
    num_accounts == 0
).CALCULATE(
    num_customers_without_account=RELCOUNT(customer_id)
)

# Step 1: Find the minimum surface area among countries in Europe
min_europe_surface_area_value = GRAPH.CALCULATE(
    min_area=MIN(countries.WHERE(Continent == "Europe").SurfaceArea)
).SINGULAR().min_area

# Step 2: Filter all countries to find those with a surface area greater than this minimum
result = countries.WHERE(
    SurfaceArea > min_europe_surface_area_value
).CALCULATE(
    country_name=name
)

teacher_for_math_course = course_teach.course_arranges.WHERE(
    course.course == 'Math'
).CALCULATE(
    teacher_name=teacher.name
)

region_group_counts = drama_workshop_group.PARTITION(
    name="regions",
    by=marketing_region_code
).CALCULATE(
    marketing_region_code=marketing_region_code,
    num_groups=COUNT(drama_workshop_group)
)

most_active_region_code = region_group_counts.TOP_K(
    1,
    by=num_groups.DESC()
).CALCULATE(
    region_code=marketing_region_code
)

hawaii_wisconsin_professionals_emails = professional.WHERE(
    ISIN(state, ("Hawaii", "Wisconsin"))
).CALCULATE(
    email_address=email_address
)

most_recent_complaint_customer_phone = complaint.TOP_K(
    1, by=date_complaint_raised.DESC(na_pos='last')
).SINGULAR().customer.CALCULATE(
    customer_phone_number=phone_number
)

london_employees = hr_1.employee.WHERE(
    hr_1.location.WHERE(
        location_id == employee.department.location_id
    ).SINGULAR().city == 'London'
).CALCULATE(
    full_employee_name=JOIN_STRINGS(' ', first_name, last_name),
    employee_salary=salary
)

num_institutions_without_proteins = institutions.WHERE(
    HASNOT(proteins) == 1
).CALCULATE(
    count_institutions=COUNT(institution_id)
)
